<content><![CDATA[
import React from 'react';
import { Home, BookOpen, Library, User, Users } from 'lucide-react';
import { ViewState } from '../types';

interface NavigationProps {
  currentView: ViewState;
  onViewChange: (view: ViewState) => void;
}

const Navigation: React.FC<NavigationProps> = ({ currentView, onViewChange }) => {
  const navItems = [
    { id: ViewState.HOME, icon: Home, label: '首页' },
    { id: ViewState.COURSES, icon: BookOpen, label: '课程' },
    { id: ViewState.COMMUNITY, icon: Users, label: '校友圈' }, // Restored to center
    { id: ViewState.LIBRARY, icon: Library, label: '图书馆' },
    { id: ViewState.PROFILE, icon: User, label: '我的' },
  ];

  return (
    <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-slate-200 pb-safe-area shadow-[0_-4px_10px_rgba(0,0,0,0.03)] z-50">
      <div className="flex justify-around items-center h-16">
        {navItems.map((item) => {
          const isActive = currentView === item.id;
          const Icon = item.icon;
          return (
            <button
              key={item.id}
              onClick={() => onViewChange(item.id)}
              className={`flex flex-col items-center justify-center w-full h-full space-y-1 transition-colors duration-200 ${
                isActive ? 'text-blue-900' : 'text-slate-400 hover:text-slate-600'
              }`}
            >
              <Icon
                size={24}
                className={isActive ? 'fill-blue-50 stroke-blue-900' : ''}
                strokeWidth={isActive ? 2.5 : 2}
              />
              <span className={`text-[10px] font-bold ${isActive ? 'text-blue-900' : 'text-slate-500'}`}>
                {item.label}
              </span>
            </button>
          );
        })}
      </div>
    </div>
  );
};

export default Navigation;
]]></content>
</change>

