import CoursesView from './components/CoursesView';
import CommunityView from './components/CommunityView';
import LibraryView from './components/LibraryView';
import ProfileView from './components/ProfileView';
import CollegeView from './components/CollegeView';
import { ViewState } from './types';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.HOME);

  const getTitle = (view: ViewState) => {
    switch (view) {
      case ViewState.HOME: return 'AMAS';
      case ViewState.COLLEGE_OVERVIEW: return '学院概览';
      case ViewState.COURSES: return '神学课程';
      case ViewState.COMMUNITY: return '校友信仰圈';
      case ViewState.LIBRARY: return '图书馆';
      case ViewState.PROFILE: return '学生档案';
      default: return 'AMAS';
    }
  };

  const handleChatClick = () => {
    alert("即时通讯功能即将上线！");
  };

  const handleBackToHome = () => {
    setCurrentView(ViewState.HOME);
  };

  return (
    <div className="bg-slate-100 min-h-screen font-sans text-slate-900">
      {/* Only show Header if NOT on Home screen */}
      {currentView !== ViewState.HOME && (
        <Header 
          title={getTitle(currentView)} 
          onChatClick={handleChatClick} 
          showBack={currentView === ViewState.COLLEGE_OVERVIEW}
          onBack={handleBackToHome}
        />
      )}

      {/* Container restricts width for desktop but is full width mobile */}
      <main className="max-w-md mx-auto bg-slate-50 min-h-screen relative shadow-xl border-x border-slate-200">
        {currentView === ViewState.HOME && (
          <Dashboard onViewChange={setCurrentView} onChatClick={handleChatClick} />
        )}
        {currentView === ViewState.COLLEGE_OVERVIEW && (
          <CollegeView onBack={handleBackToHome} />
        )}
        {currentView === ViewState.COURSES && <CoursesView />}
        {currentView === ViewState.COMMUNITY && <CommunityView />}
        {currentView === ViewState.LIBRARY && <LibraryView />}
        {currentView === ViewState.PROFILE && <ProfileView />}
      </main>

      <Navigation 
        currentView={currentView === ViewState.COLLEGE_OVERVIEW ? ViewState.HOME : currentView} 
        onViewChange={setCurrentView} 
      />
    </div>
  );
};

export default App;
