  isMicOn: boolean;
  setIsMicOn: (v: boolean) => void;
  showToast: (msg: string) => void;
  contacts: Contact[];
  initialChats: ChatMessage[];
}

const VoiceRoomOverlay: React.FC<VoiceRoomOverlayProps> = ({
  activeVoiceRoom, isRoomMinimized, setIsRoomMinimized, setActiveVoiceRoom,
  isMicOn, setIsMicOn, showToast, contacts, initialChats
}) => {
    const [chatInput, setChatInput] = useState("");
    const [showMenu, setShowMenu] = useState(false);
    const [showGiftPanel, setShowGiftPanel] = useState(false);
    const [showRoomInfo, setShowRoomInfo] = useState(false);

    // New States for Enhanced Features
    const [showPlaylist, setShowPlaylist] = useState(false);
    const [showSettings, setShowSettings] = useState(false);
    const [showInvite, setShowInvite] = useState(false);
    const [isPlaying, setIsPlaying] = useState(true);
    const [currentSong, setCurrentSong] = useState(PRAISE_SONGS[0]);
    const [musicVolume, setMusicVolume] = useState(50);
    const [vocalVolume, setVocalVolume] = useState(80);

    const [roomChats, setRoomChats] = useState<ChatMessage[]>(initialChats);

    // --- Gemini Live Integration State ---
    const [isAiConnected, setIsAiConnected] = useState(false);
    const [isAiSpeaking, setIsAiSpeaking] = useState(false);
    const [isAiLoading, setIsAiLoading] = useState(false);

    // Local Participants State
    const [participants, setParticipants] = useState([
        { id: 'pastor', name: '李牧师', avatar: 'https://picsum.photos/100/100?random=p', isSpeaking: false, role: 'host' },
        { id: 'me', name: '我', avatar: 'https://picsum.photos/200/200?random=me', isSpeaking: false, role: 'listener' },
        { id: 'u1', name: '张大卫', avatar: 'https://picsum.photos/100/100?random=u1', isSpeaking: false, role: 'speaker' },
        { id: 'u2', name: 'Hannah', avatar: 'https://picsum.photos/100/100?random=u2', isSpeaking: false, role: 'listener' },
        { id: 'u3', name: 'Grace', avatar: 'https://picsum.photos/100/100?random=u3', isSpeaking: false, role: 'listener' },
        { id: 'u4', name: 'Simon', avatar: 'https://picsum.photos/100/100?random=u4', isSpeaking: false, role: 'listener' },
        { id: 'u5', name: 'Peter', avatar: 'https://picsum.photos/100/100?random=u5', isSpeaking: false, role: 'listener' },
        { id: 'u6', name: 'John', avatar: 'https://picsum.photos/100/100?random=u6', isSpeaking: false, role: 'listener' },
    ]);

    const me = participants.find(p => p.id === 'me');
    const isOnStage = me?.role !== 'listener';

    const [reactions, setReactions] = useState<{id: number, emoji: string, left: number}[]>([]);
    const chatContainerRef = useRef<HTMLDivElement>(null);

    // Theme determination
    const isPrayerRoom = activeVoiceRoom.id.includes('prayer');
    const isPraiseRoom = activeVoiceRoom.id.includes('praise');

    const bgGradient = isPrayerRoom 
      ? 'bg-gradient-to-b from-rose-950 via-slate-900 to-black' 
      : (isPraiseRoom ? 'bg-gradient-to-b from-amber-950 via-slate-900 to-black' : 'bg-gradient-to-b from-slate-900 via-blue-950 to-black');

    // --- Gemini Live API Logic ---
    const audioContextRef = useRef<AudioContext | null>(null);
    const inputAudioContextRef = useRef<AudioContext | null>(null);
    const aiClientRef = useRef<GoogleGenAI | null>(null);
    const nextStartTimeRef = useRef<number>(0);
    const sessionRef = useRef<any>(null);
    const micStreamRef = useRef<MediaStream | null>(null);
    const processorRef = useRef<ScriptProcessorNode | null>(null);

    // Update Participants visual state
    useEffect(() => {
      setParticipants(prev => prev.map(p => {
        if (p.id === 'pastor') return { ...p, isSpeaking: isAiSpeaking };
        if (p.id === 'me') return { ...p, isSpeaking: isMicOn };
        return p;
      }));
    }, [isAiSpeaking, isMicOn]);

    useEffect(() => {
      // Cleanup on unmount
      return () => {
        disconnectFromGemini();
      };
    }, []);

    const connectToGemini = async () => {
      try {
        setIsAiLoading(true);
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        aiClientRef.current = ai;

        // Setup Audio Contexts
        const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
        // Output audio context (for AI voice)
        audioContextRef.current = new AudioContextClass({ sampleRate: SAMPLE_RATE });
        // Input audio context (for Mic)
        inputAudioContextRef.current = new AudioContextClass({ sampleRate: 16000 });

        // Microphone Setup
        const stream = await navigator.mediaDevices.getUserMedia({ audio: {
          channelCount: 1,
          sampleRate: 16000,
        }});
        micStreamRef.current = stream;

        // Live Connection
        const sessionPromise = ai.live.connect({
          model: 'gemini-2.5-flash-native-audio-preview-09-2025',
          callbacks: {
            onopen: () => {
              console.log("Gemini Live Connected");
              setIsAiConnected(true);
              setIsAiLoading(false);
              showToast("已连接到语音牧师");

              // Stream audio from the microphone to the model.
              const source = inputAudioContextRef.current!.createMediaStreamSource(stream);
              const processor = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);
              processorRef.current = processor;

              processor.onaudioprocess = (e) => {
                // Only send audio if the user's mic is on and enabled in UI
                if (!isMicOn) return; 

                const inputData = e.inputBuffer.getChannelData(0);
                const pcmData = floatTo16BitPCM(inputData);
                const base64Data = arrayBufferToBase64(pcmData.buffer);

                sessionPromise.then(session => {
                   session.sendRealtimeInput({
                      media: {
                        mimeType: "audio/pcm",
                        data: base64Data
                      }
                   });
                });
              };

              source.connect(processor);
              processor.connect(inputAudioContextRef.current!.destination);
            },
            onmessage: async (message: LiveServerMessage) => {
               // Handle AI Audio Output
               const audioData = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
               if (audioData) {
                  // Visual Indicator for AI Speaking
                  setIsAiSpeaking(true);

                  const ctx = audioContextRef.current!;
                  const audioBytes = base64ToUint8Array(audioData);

                  // Decoding raw PCM (16-bit, 24kHz mono) to AudioBuffer
                  const audioBuffer = ctx.createBuffer(1, audioBytes.length / 2, SAMPLE_RATE);
                  const channelData = audioBuffer.getChannelData(0);
                  const view = new DataView(audioBytes.buffer);
                  for(let i=0; i < audioBytes.length / 2; i++){
                      // Read int16 (Little Endian) and normalize to float [-1.0, 1.0]
                      const pcm16 = view.getInt16(i * 2, true);
                      channelData[i] = pcm16 / 32768.0;
                  }

                  const source = ctx.createBufferSource();
                  source.buffer = audioBuffer;
                  source.connect(ctx.destination);

                  // Gapless playback scheduling
                  const now = ctx.currentTime;
                  const start = Math.max(now, nextStartTimeRef.current);
                  source.start(start);
                  nextStartTimeRef.current = start + audioBuffer.duration;

                  source.onended = () => {
                     // If playback queue catches up to current time, AI stopped speaking
                     if (ctx.currentTime >= nextStartTimeRef.current - 0.1) {
                        setIsAiSpeaking(false);
                     }
                  };
               }

               if (message.serverContent?.turnComplete) {
                  setIsAiSpeaking(false);
               }
            },
            onclose: () => {
               console.log("Gemini Live Closed");
               setIsAiConnected(false);
               setIsAiSpeaking(false);
            },
            onerror: (e) => {
               console.error("Gemini Live Error", e);
               setIsAiConnected(false);
               setIsAiLoading(false);
               setIsAiSpeaking(false);
            }
          },
          config: {
            responseModalities: [Modality.AUDIO],
            systemInstruction: "You are Pastor Li, a wise and caring pastor at the Asian Missionary Theological Seminary (AMAS). You are in an online prayer room. Listen to students' prayer requests, offer biblical encouragement, and pray for them. Keep your responses concise, warm, and pastoral. Use Chinese language.",
            speechConfig: {
              voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Puck' } } 
            }
          }
        });

        sessionRef.current = sessionPromise;

      } catch (error) {
        console.error("Failed to connect to Gemini", error);
        setIsAiLoading(false);
        showToast("连接失败，请重试");
      }
    };

    const disconnectFromGemini = () => {
       if (sessionRef.current) {
          // We can't explicitly close the session via API in this SDK version easily, 
          // but we can clean up local resources which stops the stream.
       }
       if (micStreamRef.current) {
          micStreamRef.current.getTracks().forEach(t => t.stop());
       }
       if (processorRef.current) {
          processorRef.current.disconnect();
       }
       if (audioContextRef.current && audioContextRef.current.state !== 'closed') {
          audioContextRef.current.close();
       }
       if (inputAudioContextRef.current && inputAudioContextRef.current.state !== 'closed') {
          inputAudioContextRef.current.close();
       }
       setIsAiConnected(false);
       setIsAiSpeaking(false);
    };


    // Auto scroll chat
    useEffect(() => {
      if (chatContainerRef.current) {
        chatContainerRef.current.scrollTop = chatContainerRef.current.scrollHeight;
      }
    }, [roomChats]);

    // Handlers
    const handleSendChat = () => {
      if (!chatInput.trim()) return;
      setRoomChats([...roomChats, { id: `m-${Date.now()}`, user: '我', userAvatar: 'https://picsum.photos/200/200?random=me', text: chatInput, type: 'text' }]);
      setChatInput("");
    };

    const handleRaiseHand = () => {
        showToast('已举手申请发言...');
        setTimeout(() => {
            setParticipants(prev => prev.map(p => p.id === 'me' ? { ...p, role: 'speaker' } : p));
            setRoomChats(prev => [...prev, { id: `sys-${Date.now()}`, user: '系统', text: '我 上麦了', type: 'system' }]);
            showToast('主持人邀请您上麦');
            // Auto connect AI when user goes on stage in Prayer room if not connected?
            // Or just visual state
            setIsMicOn(true);
        }, 2000);
    };

    const handleLeaveStage = () => {
        setParticipants(prev => prev.map(p => p.id === 'me' ? { ...p, role: 'listener', isSpeaking: false } : p));
        setRoomChats(prev => [...prev, { id: `sys-${Date.now()}`, user: '系统', text: '我 下麦了', type: 'system' }]);
        setIsMicOn(false);
        showToast('已下麦');
    };

    const toggleMic = () => {
        if (!isOnStage) return;
        setIsMicOn(!isMicOn);
        // isMicOn change triggers useEffect to update participants list
    };

    const handleShareContent = (type: 'verse' | 'hymn') => {
       const content = type === 'verse' ? '📖 [经文] 诗篇 23:1 - 耶和华是我的牧者，我必不至缺乏。' : '🎵 [诗歌] 《这一生最美的祝福》';
       setRoomChats([...roomChats, { id: `m-${Date.now()}`, user: '我', userAvatar: 'https://picsum.photos/200/200?random=me', text: content, type }]);
       setShowMenu(false);
    };

    const triggerReaction = (emoji: string = '❤️') => {
      const newReaction = {
        id: Date.now(),
        emoji: emoji,
        left: Math.random() * 70 + 15 // 15% to 85% width
      };
      setReactions(prev => [...prev, newReaction]);
      setTimeout(() => {
         setReactions(prev => prev.filter(r => r.id !== newReaction.id));
      }, 2500);
    };

    const handleSendGift = (gift: any) => {
      setRoomChats([...roomChats, { 
        id: `g-${Date.now()}`, 
        user: '我', 
        userAvatar: 'https://picsum.photos/200/200?random=me', 
        text: `送出了 ${gift.name}`, 
        type: 'gift',
        giftData: { name: gift.name, icon: gift.icon }
      }]);
      setShowGiftPanel(false);
      triggerReaction(gift.icon);
    };

    // --- Modals inside Voice Room ---

    const PlaylistModal = () => (
        <div className="absolute inset-0 z-[60] bg-black/80 backdrop-blur-sm flex items-end animate-fade-in">
           <div className="bg-slate-900 w-full rounded-t-3xl p-6 h-[60vh] flex flex-col animate-slide-up border-t border-white/10">
               <div className="flex justify-between items-center mb-4">
                   <h3 className="text-white font-bold flex items-center"><ListMusic className="mr-2"/> 赞美诗列表</h3>
                   <button onClick={() => setShowPlaylist(false)} className="p-2 bg-white/10 rounded-full text-white"><ChevronDown size={20}/></button>
               </div>
               <div className="flex-1 overflow-y-auto space-y-2 pr-1 custom-scrollbar">
                   {PRAISE_SONGS.map((song, idx) => (
                       <div 
                          key={song.id} 
                          onClick={() => { setCurrentSong(song); setIsPlaying(true); }}
                          className={`flex items-center p-3 rounded-xl cursor-pointer transition ${currentSong.id === song.id ? 'bg-amber-500/20 border border-amber-500/50' : 'hover:bg-white/5 border border-transparent'}`}
                       >
                           <div className="w-8 h-8 rounded-lg flex items-center justify-center bg-white/10 mr-3 text-xs font-bold text-slate-400">
                               {currentSong.id === song.id && isPlaying ? <div className="flex space-x-0.5 items-end h-3"><span className="w-0.5 h-3 bg-amber-400 animate-pulse"></span><span className="w-0.5 h-2 bg-amber-400 animate-pulse delay-75"></span><span className="w-0.5 h-3 bg-amber-400 animate-pulse delay-150"></span></div> : idx + 1}
                           </div>
                           <div className="flex-1">
                               <h4 className={`text-sm font-bold ${currentSong.id === song.id ? 'text-amber-400' : 'text-white'}`}>{song.title}</h4>
                               <p className="text-xs text-slate-400">{song.artist}</p>
                           </div>
                           <span className="text-xs text-slate-500">{song.duration}</span>
                       </div>
                   ))}
               </div>
           </div>
        </div>
    );

    const SettingsModal = () => (
        <div className="absolute inset-0 z-[60] bg-black/80 backdrop-blur-sm flex items-end animate-fade-in">
           <div className="bg-white w-full rounded-t-3xl p-6 animate-slide-up">
               <div className="flex justify-between items-center mb-6">
                   <h3 className="text-slate-900 font-bold text-lg">房间设置</h3>
                   <button onClick={() => setShowSettings(false)} className="p-2 bg-slate-100 rounded-full text-slate-500"><X size={20}/></button>
               </div>

               <div className="space-y-6">
                   <div>
                       <div className="flex justify-between mb-2">
                          <label className="text-sm font-bold text-slate-700 flex items-center"><Music size={16} className="mr-2"/> 音乐音量</label>
                          <span className="text-xs font-bold text-slate-400">{musicVolume}%</span>
                       </div>
                       <input 
                          type="range" min="0" max="100" value={musicVolume} 
                          onChange={(e) => setMusicVolume(parseInt(e.target.value))}
                          className="w-full h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-blue-600"
                       />
                   </div>
                   <div>
                       <div className="flex justify-between mb-2">
                          <label className="text-sm font-bold text-slate-700 flex items-center"><Mic size={16} className="mr-2"/> 人声音量</label>
                          <span className="text-xs font-bold text-slate-400">{vocalVolume}%</span>
                       </div>
                       <input 
                          type="range" min="0" max="100" value={vocalVolume} 
                          onChange={(e) => setVocalVolume(parseInt(e.target.value))}
                          className="w-full h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-blue-600"
                       />
                   </div>
               </div>
           </div>
        </div>
    );

    const InviteModal = () => (
        <div className="absolute inset-0 z-[60] bg-black/80 backdrop-blur-sm flex items-center justify-center p-6 animate-fade-in">
           <div className="bg-white w-full max-w-xs rounded-3xl p-5 animate-scale-in">
               <div className="flex justify-between items-center mb-4">
                   <h3 className="text-slate-900 font-bold">邀请校友</h3>
                   <button onClick={() => setShowInvite(false)} className="text-slate-400"><X size={20}/></button>
               </div>
               <div className="space-y-3 max-h-[300px] overflow-y-auto pr-1 custom-scrollbar">
                   {contacts.filter(c => c.status !== 'none').map(contact => (
                       <div key={contact.id} className="flex items-center justify-between p-2 hover:bg-slate-50 rounded-xl">
                           <div className="flex items-center">
                               <img src={contact.avatar} className="w-10 h-10 rounded-full mr-3 border border-slate-200"/>
                               <div>
                                   <h4 className="text-sm font-bold text-slate-800">{contact.name}</h4>
                                   <p className="text-[10px] text-slate-500">{contact.role}</p>
                               </div>
                           </div>
                           <button 
                             onClick={() => { showToast(`已邀请 ${contact.name}`); setShowInvite(false); }}
                             className="px-3 py-1.5 bg-blue-50 text-blue-600 rounded-full text-xs font-bold hover:bg-blue-100"
                           >
                               邀请
                           </button>
                       </div>
                   ))}
               </div>
           </div>
        </div>
    );

    // Important: Render nothing to the DOM if minimized, but maintain state/hooks.
    // INCREASED Z-INDEX TO 100 TO COVER MAIN NAVIGATION (z-50)
    const containerClass = `fixed inset-0 z-[100] ${bgGradient} animate-fade-in flex flex-col text-white h-[100dvh] ${isRoomMinimized ? 'hidden' : ''}`;

    return (
      <div className={containerClass}>
        {showPlaylist && <PlaylistModal />}
        {showSettings && <SettingsModal />}
        {showInvite && <InviteModal />}

        {/* Flying Reactions Container - Ensure Z-Index is LOWER than footer */}
        <div className="absolute inset-0 pointer-events-none overflow-hidden z-40">
           {reactions.map(r => (
             <div 
               key={r.id}
               className="absolute bottom-24 text-4xl animate-float-up opacity-0"
               style={{ left: `${r.left}%` }}
             >
               {r.emoji}
             </div>
           ))}
        </div>

        {/* 1. Room Header */}
        <div className="flex justify-between items-center p-4 pt-safe-top border-b border-white/10 bg-black/20 backdrop-blur-sm z-20 shrink-0">
          <button onClick={() => setIsRoomMinimized(true)} className="p-2 rounded-full hover:bg-white/10 transition">
            <Minimize2 size={20} className="text-white/80" />
          </button>
          <div className="text-center">
            <h2 className="font-bold text-sm tracking-wide text-white flex items-center justify-center">
              {activeVoiceRoom.label}
              {isPraiseRoom && <Music size={12} className="ml-2 text-amber-400"/>}
            </h2>
            <div className="flex items-center justify-center space-x-1.5 mt-0.5">
               {isAiConnected && <Wifi size={10} className="text-emerald-400"/>}
               <span className={`w-1.5 h-1.5 rounded-full ${isAiConnected ? 'bg-emerald-400' : 'bg-slate-500'} animate-pulse`}></span>
               <span className="text-[10px] text-emerald-400 font-medium">
                  {isAiConnected ? 'Live Audio Connected' : 'Room Ready'} • {participants.length}人在线
               </span>
            </div>
          </div>
          <div className="flex items-center space-x-1">
            <button onClick={() => setShowSettings(true)} className="p-2 rounded-full hover:bg-white/10 transition">
               <Settings2 size={20} className="text-white/80" />
            </button>
            <button onClick={() => setShowRoomInfo(true)} className="p-2 rounded-full hover:bg-white/10 transition">
               <MoreHorizontal size={20} className="text-white/80" />
            </button>
          </div>
        </div>

        {/* Main Content Area: Split Screen Layout */}
        <div className="flex-1 relative w-full overflow-hidden flex flex-col">

          {/* Top: Stage Area (Fixed Ratio - Adjusted to 32vh to save space for Chat) */}
          <div className="h-[32vh] shrink-0 border-b border-white/10 overflow-y-auto scrollbar-hide relative bg-black/10" onClick={() => setShowMenu(false)}>
             <div className="p-6">
                <div className="text-center mb-6 mt-2">
                   <h1 className="text-lg font-serif font-bold text-white mb-1 text-shadow-lg opacity-90">{activeVoiceRoom.desc}</h1>
                   <div className="flex justify-center">
                       <span className="bg-white/10 px-2 py-0.5 rounded text-[10px] text-white/70">ID: 8839 2024</span>
                   </div>
                </div>

                {/* Connection Status for Prayer Room */}
                {isPrayerRoom && !isAiConnected && (
                   <div className="flex justify-center mb-6">
                      <button 
                        onClick={connectToGemini}
                        disabled={isAiLoading}
                        className="flex items-center space-x-2 bg-rose-600/80 hover:bg-rose-600 text-white px-6 py-2 rounded-full text-sm font-bold shadow-lg backdrop-blur-sm transition-all disabled:opacity-50"
                      >
                         {isAiLoading ? <Loader2 size={16} className="animate-spin"/> : <Phone size={16} />}
                         <span>{isAiLoading ? '正在连接...' : '呼叫牧师 (AI Live)'}</span>
                      </button>
                   </div>
                )}

                {/* Host / Speakers Grid */}
                <div className="mb-8">
                   <div className="grid grid-cols-3 gap-4 justify-items-center">
                      {participants.filter(p => p.role === 'host' || p.role === 'speaker').map(p => (
                         <div key={p.id} className="flex flex-col items-center group cursor-pointer relative w-20">
                            <div className="relative mb-2 w-16 h-16">
                               {/* Speaking Ring Animation */}
                               {p.isSpeaking && (
                                 <>
                                   <span className={`absolute inset-0 rounded-full border-[3px] ${isPrayerRoom ? 'border-rose-400/50' : 'border-blue-400/50'} animate-ping`}></span>
                                   <span className={`absolute -inset-2 rounded-full border ${isPrayerRoom ? 'border-rose-400/20' : 'border-blue-400/20'} animate-pulse`}></span>
                                 </>
                               )}
                               {/* Avatar Container */}
                               <div className={`w-full h-full rounded-full p-[3px] ${
                                 p.isSpeaking 
                                   ? (isPrayerRoom ? 'bg-gradient-to-tr from-rose-400 to-purple-400' : 'bg-gradient-to-tr from-blue-400 to-emerald-400') 
                                   : (p.role === 'host' ? 'bg-gradient-to-tr from-amber-300 via-amber-500 to-orange-600' : 'bg-white/10')
                               }`}>
                                 <img src={p.avatar} alt={p.name} className="w-full h-full rounded-full object-cover border-2 border-slate-900" />
                               </div>
                               <span className={`absolute -bottom-1 -right-1 rounded-full p-1 shadow-lg ${p.isSpeaking ? 'bg-white text-slate-900' : 'bg-slate-800 text-white'}`}>
                                 {p.isSpeaking ? <Mic size={10} fill="currentColor" /> : <MicOff size={10} />}
                               </span>
                            </div>
                            <span className="text-xs font-bold text-white truncate w-full text-center">{p.name}</span>
                            <span className={`text-[9px] px-1.5 py-0.5 rounded-full mt-1 ${p.role === 'host' ? 'bg-gradient-to-r from-amber-500 to-orange-600 text-white shadow-sm' : 'bg-blue-500/50 text-blue-100'}`}>
                                {p.role === 'host' ? (isAiConnected && p.id === 'pastor' ? 'AI 牧师' : '主持人') : '嘉宾'}
                            </span>
                         </div>
                      ))}
                   </div>
                </div>

                {/* Praise Room Music Player */}
                {isPraiseRoom && (
                  <div className="mx-2 mb-8 bg-white/10 backdrop-blur-md rounded-xl p-3 flex items-center border border-white/10 shadow-lg cursor-pointer hover:bg-white/15 transition" onClick={() => setShowPlaylist(true)}>
                     <div className="w-12 h-12 bg-amber-500 rounded-lg flex items-center justify-center mr-3 shrink-0 shadow-md">
                        {isPlaying ? <div className="flex space-x-1 items-end h-4"><span className="w-1 h-4 bg-white animate-pulse"></span><span className="w-1 h-3 bg-white animate-pulse delay-75"></span><span className="w-1 h-4 bg-white animate-pulse delay-150"></span></div> : <Music size={24} className="text-white"/>}
