                </button>
             </div>
           )}

           {/* Gift Panel */}
           {showGiftPanel && (
             <div className="absolute bottom-full left-0 right-0 mb-0 bg-slate-800 rounded-t-2xl border-t border-slate-700 shadow-2xl animate-slide-up z-50 p-4">
