  // Room Management
  const [customRooms, setCustomRooms] = useState<Room[]>([]);
  const [isCreateRoomOpen, setIsCreateRoomOpen] = useState(false);

  // Active Room State
  const [activeVoiceRoom, setActiveVoiceRoom] = useState<Room | null>(null);
