  // UI States
  const [selectedContact, setSelectedContact] = useState<Contact | null>(null);
  const [isComposeOpen, setIsComposeOpen] = useState(false);

  // Voice Room Controls (Lifted State for Persistence when minimized)
  const [isMicOn, setIsMicOn] = useState(false);

  // Helpers
  const showToast = (msg: string) => {
    setToastMessage(msg);
    setTimeout(() => setToastMessage(null), 2500);
  };

  // Helper to determine avatar border gradient
  const getAvatarGradient = (role: string = '', status: string = '') => {
    // Priority 1: Gold for Admin, Host, Alumni Staff, Professors
    if (role.includes('校友会') || role.includes('教授') || role === 'host' || role.includes('admin')) {
      return 'from-amber-300 via-amber-400 to-orange-500';
    }
    // Priority 2: Blue/Teal for Connected/Friends
    if (status === 'connected') {
      return 'from-blue-400 via-cyan-400 to-teal-400';
    }
    // Default: Subtle Slate
    return 'from-slate-200 to-slate-300';
  };

  // --- Handlers: Posts ---
  const handleLike = (id: string) => {
    setPosts(posts.map(post => 
      post.id === id ? { ...post, likedByMe: !post.likedByMe, likes: post.likedByMe ? post.likes - 1 : post.likes + 1 } : post
    ));
  };

  const handleFeedConnect = (postId: string) => {
    setPosts(posts.map(post => post.id === postId ? { ...post, connectionStatus: 'sent' } : post));
    showToast('已发送好友申请');
  };

  const handleSharePost = async (post: CommunityPost) => {
    const shareData = {
      title: `AMAS - ${post.userName} 的动态`,
      text: post.content,
      url: window.location.href, // Ideally this would be a unique URL for the post
    };

    if (navigator.share) {
      try {
        await navigator.share(shareData);
      } catch (err) {
        console.debug('Share canceled');
      }
    } else {
      // Fallback
      navigator.clipboard.writeText(`${shareData.title}\n${shareData.text}\n${shareData.url}`);
      showToast('已复制内容');
    }
  };

  // --- Handlers: Contacts ---
  const handleContactAction = (id: string, action: 'send' | 'accept' | 'decline' | 'view') => {
    if (action === 'view') {
      const contact = contacts.find(c => c.id === id);
      if (contact) setSelectedContact(contact);
      return;
    }

    setContacts(contacts.map(c => {
      if (c.id !== id) return c;
      if (action === 'send') return { ...c, status: 'sent' };
      if (action === 'decline') return { ...c, status: 'none' };
      if (action === 'accept') return { 
        ...c, 
        status: 'connected',
        contactInfo: c.contactInfo || { phone: '+852 1234 5678', email: `${c.id}@amas.hk` }
      };
      return c;
    }));

