                                      alt={msg.user} 
                                      className="w-full h-full object-cover" 
                                    />
                                </div>
                              </div>

                              <div className={`flex flex-col ${isMe ? 'items-end' : 'items-start'}`}>
                                 {!isMe && <span className="text-[10px] text-white/60 ml-1 mb-0.5">{msg.user}</span>}

                                 {msg.type === 'gift' ? (
                                    <div className="rounded-2xl py-1.5 px-3 bg-gradient-to-r from-amber-600/40 to-orange-600/40 backdrop-blur-md border border-amber-500/30 shadow-sm flex items-center text-xs text-white">
                                       <span className="font-bold mr-1 text-amber-50">{msg.user}</span>
                                       <span className="opacity-80 text-[10px] mr-1">送出了</span>
                                       <span className="font-bold text-amber-200">{msg.giftData?.name}</span>
                                       <span className="text-lg ml-1">{msg.giftData?.icon}</span>
                                    </div>
                                 ) : (
                                    <div className={`px-3.5 py-2 rounded-2xl text-sm backdrop-blur-md shadow-sm border text-white/95 leading-relaxed
                                        ${isMe 
                                            ? 'bg-gradient-to-br from-blue-600/40 to-blue-500/40 border-blue-400/20 rounded-br-none' 
                                            : (msg.type === 'verse' 
                                                ? 'bg-emerald-900/40 border-emerald-500/30 rounded-bl-none'
                                                : (msg.type === 'hymn' 
                                                    ? 'bg-amber-900/40 border-amber-500/30 rounded-bl-none'
                                                    : 'bg-white/10 border-white/10 rounded-bl-none'
                                                  )
                                              )
                                        }
                                    `}>
                                       <span className="drop-shadow-md">{msg.text}</span>
                                    </div>
                                 )}
                              </div>
                           </div>
                        </div>
                      );
                    })}
                </div>
             </div>
          </div>
        </div>

        {/* 4. Bottom Controls (Footer) - Redesigned for visibility & Dark Theme */}
        {/* Changed background to transparent/dark glass and removed high z-index conflict */}
