           {/* Action Menu Popup */}
           {showMenu && (
             <div className="absolute bottom-full left-4 mb-2 w-48 bg-slate-800 rounded-xl border border-slate-700 shadow-2xl overflow-hidden animate-scale-in origin-bottom-left z-50">
