                   <BookOpen size={16} className="mr-2 text-emerald-400"/> 分享经文
                </button>
                <button onClick={() => handleShareContent('hymn')} className="w-full text-left px-4 py-3 hover:bg-white/5 flex items-center text-sm text-white border-b border-white/5">
                   <Music size={16} className="mr-2 text-amber-400"/> 分享诗歌
                </button>
                {isOnStage && (
                    <button onClick={handleLeaveStage} className="w-full text-left px-4 py-3 hover:bg-white/5 flex items-center text-sm text-rose-400">
                       <LogOut size={16} className="mr-2"/> 下麦
                    </button>
                )}
                <button onClick={() => setShowInvite(true)} className="w-full text-left px-4 py-3 hover:bg-white/5 flex items-center text-sm text-white">
                   <UserPlus2 size={16} className="mr-2 text-blue-400"/> 邀请好友
                </button>
             </div>
           )}

           {/* Gift Panel */}
           {showGiftPanel && (
             <div className="absolute bottom-full left-0 right-0 mb-0 bg-slate-800 rounded-t-2xl border-t border-slate-700 shadow-2xl animate-slide-up z-50 p-4">
