                </div>
                <div className="grid grid-cols-5 gap-2">
                   {GIFT_ITEMS.map(gift => (
                      <button key={gift.id} onClick={() => handleSendGift(gift)} className="flex flex-col items-center p-2 rounded-xl hover:bg-white/10 transition">
