                         <span className="text-[10px] text-white font-medium">{gift.name}</span>
                         <span className="text-[9px] text-slate-400 flex items-center mt-0.5">
                            <div className="w-2 h-2 bg-amber-400 rounded-full mr-1"></div> {gift.cost}
                         </span>
                      </button>
                   ))}
                </div>
             </div>
           )}

           {/* Control Bar - High Contrast & Better Layout */}
           <div className="flex items-center space-x-2">
              {/* More Button - Increased size for touch */}
              <button 
                 onClick={() => setShowMenu(!showMenu)} 
                 className="shrink-0 w-12 h-12 rounded-full bg-white/10 text-slate-300 border border-white/5 flex items-center justify-center hover:bg-white/20 transition active:scale-95"
              >
                 <Plus size={24} />
              </button>

              {/* Enhanced Input Bar - Dark Translucent Theme - Taller */}
              <div className="flex-1 bg-white/10 hover:bg-white/15 transition-colors rounded-full px-1 py-1 flex items-center border border-white/5 focus-within:border-white/20 focus-within:bg-white/20 h-12">
                 <input 
                   type="text" 
                   value={chatInput}
                   onChange={(e) => setChatInput(e.target.value)}
                   onKeyDown={(e) => e.key === 'Enter' && handleSendChat()}
                   placeholder="发送消息..." 
                   className="bg-transparent border-none outline-none text-sm text-white placeholder-white/40 flex-1 min-w-0 px-3" 
                 />
                 {chatInput.trim() ? (
                    <button onClick={handleSendChat} className="w-10 h-10 rounded-full bg-blue-600 text-white flex items-center justify-center hover:bg-blue-700 transition mr-0.5">
                       <Send size={16} />
                    </button>
                 ) : (
                    <div className="w-10 h-10 rounded-full flex items-center justify-center">
                        <MessageCircle size={20} className="text-white/20" />
                    </div>
                 )}
              </div>

              {/* Mic or Hand Raise (Right Side Primary Action) - Increased size */}
              {isOnStage ? (
                 <button 
                     onClick={toggleMic} 
                     className={`shrink-0 w-12 h-12 rounded-full flex items-center justify-center transition-all shadow-lg ${
                        isMicOn ? 'bg-blue-600 text-white ring-2 ring-white/20' : 'bg-white/10 text-slate-300 hover:bg-white/20 border border-white/5'
                     }`}
                 >
                     {isMicOn ? <Mic size={22} className="animate-pulse"/> : <MicOff size={22} />}
                 </button>
              ) : (
                 <button 
                     onClick={handleRaiseHand} 
                     className="shrink-0 w-12 h-12 rounded-full flex items-center justify-center transition-all shadow-lg bg-white/10 text-slate-300 border border-white/5 hover:bg-white/20 active:scale-95"
                 >
                     <Hand size={22} />
                 </button>
              )}

              {/* Gift - Increased size */}
              <button 
                 onClick={() => setShowGiftPanel(!showGiftPanel)}
                 className="shrink-0 w-12 h-12 rounded-full flex items-center justify-center bg-gradient-to-br from-amber-500 to-orange-600 text-white shadow-lg hover:brightness-110 transition active:scale-95"
              >
                 <Gift size={22} />
              </button>

              {/* Reaction Heart (Quick Action) - Increased size */}
               <button onClick={() => triggerReaction()} className="shrink-0 w-12 h-12 rounded-full text-rose-400 hover:bg-white/10 transition flex items-center justify-center bg-white/5 border border-white/5">
                   <Heart size={22} fill="currentColor"/>
               </button>
           </div>
        </div>

        {/* Room Info Modal */}
        {showRoomInfo && (
           <div className="absolute inset-0 z-[70] bg-black/80 backdrop-blur-sm flex items-center justify-center p-6 animate-fade-in" onClick={() => setShowRoomInfo(false)}>
              <div className="bg-white w-full max-w-xs rounded-2xl p-6 relative text-slate-900" onClick={e => e.stopPropagation()}>
                 <div className="flex items-center justify-center mb-4">
                    <div className={`w-16 h-16 rounded-full flex items-center justify-center ${isPrayerRoom ? 'bg-rose-100 text-rose-600' : 'bg-blue-100 text-blue-600'}`}>
                       {activeVoiceRoom.icon && <activeVoiceRoom.icon size={32} />}
                    </div>
                 </div>
                 <h3 className="text-lg font-bold text-center mb-2">{activeVoiceRoom.label}</h3>
                 <div className="bg-slate-50 p-3 rounded-xl border border-slate-100 mb-4">
                    <h4 className="text-xs font-bold text-slate-500 mb-1 uppercase">公告</h4>
                    <p className="text-sm text-slate-700 leading-relaxed">{activeVoiceRoom.announcement || '暂无公告'}</p>
                 </div>

                 {isAiConnected && (
                    <div className="mb-4 flex items-center justify-center text-xs text-emerald-600 bg-emerald-50 p-2 rounded-lg border border-emerald-100">
                       <Wifi size={14} className="mr-1.5"/> 语音牧师在线
                    </div>
                 )}

                 <div className="space-y-2">
                    <button className="w-full py-3 bg-slate-100 text-slate-600 font-bold rounded-xl hover:bg-slate-200 text-sm flex items-center justify-center">
                       <Share2 size={16} className="mr-2"/> 分享房间
                    </button>
                    <button onClick={() => { disconnectFromGemini(); setActiveVoiceRoom(null); setShowRoomInfo(false);}} className="w-full py-3 bg-rose-50 text-rose-600 font-bold rounded-xl hover:bg-rose-100 text-sm flex items-center justify-center">
                       <PhoneOff size={16} className="mr-2"/> 退出房间
                    </button>
                 </div>
                 <button onClick={() => setShowRoomInfo(false)} className="absolute top-4 right-4 text-slate-400 hover:text-slate-600">
                    <X size={20} />
                 </button>
              </div>
           </div>
        )}
      </div>
    );

    return createPortal(overlayContent, document.body);
};

